-- Trade Checker 테스트 데이터 (실서비스 모드용)
-- 사용법
--   1) 사이트에서 테스트용 이메일로 먼저 회원가입합니다.
--   2) 아래 v_email 값을 그 이메일로 바꿉니다.
--   3) Supabase → SQL Editor 에 붙여 넣고 Run.
-- 같은 계정에 다시 실행하면 이 스크립트가 넣은 테스트 데이터만 지우고 새로 넣습니다.
-- 모든 회사는 가상 데이터입니다.

do $$
declare
  v_email text := 'test1@example.com';   -- ← 가입한 테스트 이메일로 바꾸세요
  v_uid uuid;
  v_rep uuid;
  v_ids jsonb := '{}'::jsonb;
begin
  select id into v_uid from auth.users where lower(email) = lower(v_email);
  if v_uid is null then
    raise exception '% 로 가입된 계정이 없습니다. 사이트에서 먼저 회원가입해 주세요.', v_email;
  end if;

  -- 이전에 넣은 테스트 데이터 정리 (TC-TEST- 주문, 이 스크립트의 리포트·관심 거래처)
  delete from public.watchlist where user_id = v_uid and company_id in ('kestrel-nl','riyadh-sa','warsaw-pl');
  delete from public.orders where user_id = v_uid and id like 'TC-TEST-%';
  delete from public.reports where user_id = v_uid and company_id in ('sakura-jp','kestrel-nl','nw-global-ae','riyadh-sa','warsaw-pl','lagos-ng','apex-ae','sinoglobal-hk');

  -- 1. 요금제: Starter (25일 남음), 이번 주기 4건 사용, 단건 크레딧 2건
  insert into public.profiles (id, email) values (v_uid, v_email) on conflict (id) do nothing;
  update public.profiles
     set plan = 'starter', plan_expires_at = now() + interval '25 days',
         period_start = current_date - 5, period_used = 4, credits = 2
   where id = v_uid;

  -- 2. 조회 기록 8건 (A·B·C·C·D·D·F·F)
  insert into public.reports (user_id, query, company_id, company_name, country, grade, risk_points, result, created_at)
